"""Build a portable HTML from the exact hosted source; no CDN or server needed."""
from pathlib import Path
import base64,json,re
p=Path(__file__).resolve().parent;d=p/'dist'
def module(s):return 'data:text/javascript;base64,'+base64.b64encode(s.encode()).decode()
imports={}
for key,file in [('three','vendor/three.module.js'),('gltf-loader','vendor/GLTFLoader.js'),('orbit-controls','vendor/OrbitControls.js'),('room-environment','vendor/RoomEnvironment.js'),('geometry-utils','vendor/BufferGeometryUtils.js'),('streetcar-controller','streetcar-controller.js'),('queen-routes-data','routes-data.js'),('queen-routes','routes.js'),('queen-route-signs','route-signs.js'),('queen-dundas-districts','dundas-districts.js'),('queen-dundas-scenery','dundas-scenery.js'),('queen-dundas-retail','dundas-retail.js'),('queen-dundas-facades','dundas-facades.js'),('queen-facade-windows','facade-windows.js'),('queen-environment','environment.js'),('queen-street-life','street-life.js'),('queen-neighbourhood','neighbourhood.js'),('queen-ride','ride.js'),('queen-cameras','cameras.js'),('queen-sounds','sounds.js'),('queen-sensory-controls','sensory-controls.js'),('queen-app','app.js'),('queen-lighting','lighting.js'),('queen-surfaces','surfaces.js'),('queen-rendering','rendering.js'),('queen-shadow-bias','shadow-bias.js'),('queen-day-night','day-night.js'),('queen-streetcar-asset','streetcar-asset.js'),('queen-streetcar-traffic','streetcar-traffic.js'),('queen-car-assets','car-assets.js'),('queen-streetscape','streetscape.js'),('queen-traffic-flow','traffic-flow.js'),('queen-night-windows','night-windows.js'),('queen-architecture','architecture.js'),('queen-weather','weather.js'),('queen-weather-cycle','weather-cycle.js'),('queen-performance','performance.js'),('queen-loading','loading.js')]:
    source=(d/file).read_text(encoding='utf8').replace('../utils/BufferGeometryUtils.js','geometry-utils').replace("'./street-life.js'","'queen-street-life'").replace("'./neighbourhood.js'","'queen-neighbourhood'").replace("'./ride.js'","'queen-ride'").replace("'./cameras.js'","'queen-cameras'").replace("'./sounds.js'","'queen-sounds'").replace("'./sounds.js?timing-v11'","'queen-sounds'").replace("'./surfaces.js'","'queen-surfaces'").replace("'./rendering.js'","'queen-rendering'")
    source=source.replace("'./facade-windows.js'","'queen-facade-windows'")
    source=source.replace("'./dundas-retail.js'","'queen-dundas-retail'").replace("'./dundas-facades.js'","'queen-dundas-facades'")
    source=source.replace("'./dundas-districts.js'","'queen-dundas-districts'").replace("'./dundas-scenery.js'","'queen-dundas-scenery'")
    source=source.replace("'./routes-data.js'","'queen-routes-data'").replace("'./routes.js'","'queen-routes'").replace("'./route-signs.js'","'queen-route-signs'")
    source=source.replace("'./sensory-controls.js'","'queen-sensory-controls'").replace("'./night-windows.js'","'queen-night-windows'").replace("'./traffic-flow.js'","'queen-traffic-flow'").replace("'./shadow-bias.js'","'queen-shadow-bias'").replace("'./car-assets.js'","'queen-car-assets'").replace("'./streetscape.js'","'queen-streetscape'").replace("'./architecture.js'","'queen-architecture'").replace("'./weather.js'","'queen-weather'")
    source=source.replace("'./performance.js'","'queen-performance'").replace("'./loading.js'","'queen-loading'").replace("'./weather-cycle.js'","'queen-weather-cycle'").replace("'./day-night.js'","'queen-day-night'").replace("'./streetcar-asset.js'","'queen-streetcar-asset'").replace("'./streetcar-traffic.js'","'queen-streetcar-traffic'")
    imports[key]=module(source)
html=(d/'index.html').read_text(encoding='utf8')
html=html.replace('<link rel="stylesheet" href="style.css">','<style>'+(d/'style.css').read_text(encoding='utf8')+'</style>')
html=re.sub(r'<script type="importmap">.*?</script>','<script type="importmap">'+json.dumps({'imports':imports})+'</script>',html,flags=re.S)
main=(d/'main.js').read_text(encoding='utf8').replace("'./performance.js'","'queen-performance'").replace("'./loading.js'","'queen-loading'").replace("'./environment.js'","'queen-environment'").replace("'./app.js'","'queen-app'").replace("'./lighting.js'","'queen-lighting'").replace("'./surfaces.js'","'queen-surfaces'").replace("'./rendering.js'","'queen-rendering'").replace("'./car-assets.js'","'queen-car-assets'").replace("'./streetscape.js'","'queen-streetscape'").replace("'./architecture.js'","'queen-architecture'").replace("'./weather.js'","'queen-weather'")
main=main.replace("'./routes.js'","'queen-routes'")
html=html.replace('<script type="module" src="main.js"></script>','<script id="embedded-car" type="application/octet-stream">'+base64.b64encode((d/'ttc-clrv.glb').read_bytes()).decode()+'</script><script id="embedded-traffic-cars" type="application/octet-stream">'+base64.b64encode((d/'traffic-cars.glb').read_bytes()).decode()+'</script><script id="embedded-street-props" type="application/octet-stream">'+base64.b64encode((d/'street-props.glb').read_bytes()).decode()+'</script><script type="module">'+main+'</script>')
html=html.replace('</body>','<script id="embedded-architecture" type="application/octet-stream">'+base64.b64encode((d/'architecture.glb').read_bytes()).decode()+'</script></body>')
for name,file in [('bell','streetcar-bell.wav'),('horn','streetcar-horn.wav'),('streetcar-pass','streetcar-pass.wav'),('door','streetcar-door.wav')]:
    html=html.replace('</body>','<script id="audio-'+name+'" type="application/octet-stream">'+base64.b64encode((d/'audio'/file).read_bytes()).decode()+'</script></body>')
(p/'Queen-Street-Drive.html').write_text(html,encoding='utf8')
print('Portable HTML:',len(html),'characters')
